use crate::{Config,Service,Result,need,clock,now,money};
use baal_transport_service::{Transport,Endpoint,Receipt,Authority,Scope,RequestSpec,Permit,TransportError,AccountReconciliation};
use serde::{Serialize,Deserialize};
use serde_json::{Value,json};
use std::{path::PathBuf,fs,collections::BTreeSet};
#[derive(Clone,Deserialize,Serialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]pub struct MigrationPermit{pub owner:String,pub handoff_id:String,pub observed_at:String,pub expires_at:String,pub legacy_lock_path:PathBuf,pub legacy_stop_path:PathBuf,pub legacy_rate_path:PathBuf}
pub struct ServiceReadAuthority{pub scope:Scope,pub owner_path:PathBuf,pub owner_token:String,pub stops:Vec<PathBuf>,pub migration:Option<MigrationPermit>}
impl Authority for ServiceReadAuthority{
 fn can_read(&self,scope:&Scope)->bool{if scope.tournament_id!=self.scope.tournament_id||scope.tournament_slug!=self.scope.tournament_slug||scope.exchanges!=self.scope.exchanges||self.stops.iter().any(|p|p.exists())||fs::read_to_string(&self.owner_path).ok().as_deref()!=Some(&self.owner_token){return false}if let Some(p)=&self.migration{let Ok(t)=clock(&now())else{return false};if p.owner!="Codex"||p.handoff_id.is_empty()||!p.legacy_lock_path.is_absolute()||!p.legacy_stop_path.is_absolute()||p.legacy_lock_path.exists()||!p.legacy_stop_path.is_file()||!clock(&p.observed_at).is_ok_and(|o|o<=t)||!clock(&p.expires_at).is_ok_and(|e|e>t){return false}}true}
 fn authorize(&self,_:&Scope,_:&RequestSpec,_:&Permit,_:bool,_:u64)->std::result::Result<(),TransportError>{Err(TransportError{code:"WRITES_DISABLED".into(),status:None,may_have_executed:false,retry_after_ms:0,order_id:None,api_code:None})}
 fn owns_order(&self,_:&str)->bool{false}
}
pub fn normalize_book(receipt:&Receipt,market:&str,config:&Config)->Result<Value>{need(receipt.status==200,"SERVICE_BOOK_STATUS")?;let received=clock(&receipt.received_at)?;let started=clock(&receipt.request_started_at)?;need(received>=started&&received-started<=20000,"SERVICE_BOOK_RECEIPT_AGE")?;let contexts=receipt.data["contexts"].as_array().ok_or("SERVICE_BOOK_CONTEXT")?;need(contexts.len()==1&&contexts[0]["type"]=="tournament"&&contexts[0]["tournament"]["id"]==config.tournament_id,"SERVICE_BOOK_SCOPE")?;let rows=contexts[0]["orderbook"]["exchanges"].as_array().ok_or("SERVICE_BOOK_EXCHANGE")?;need(rows.len()==1&&rows[0]["option"]=="YES","SERVICE_BOOK_EXCHANGE")?;let exchange=rows[0]["exchangeId"].as_str().ok_or("SERVICE_BOOK_EXCHANGE")?;need(config.exchanges.get(exchange).is_some_and(|m|m==market),"SERVICE_BOOK_EXCHANGE")?;let version=&rows[0]["asOf"];let sequence=version["sequence"].as_u64().ok_or("SERVICE_BOOK_VERSION")?;need(sequence<=9007199254740991,"SERVICE_BOOK_VERSION")?;let raw=version["at"].as_str().ok_or("SERVICE_BOOK_VERSION")?;let parsed=chrono::DateTime::parse_from_rfc3339(raw).map_err(|_|"SERVICE_BOOK_VERSION")?;let source_ms=parsed.timestamp_millis();need(source_ms<=received+2000,"SERVICE_BOOK_VERSION")?;let source_at=parsed.to_rfc3339_opts(chrono::SecondsFormat::Nanos,true);
 let levels=|key:&str,desc:bool|->Result<Value>{let input=rows[0][key].as_array().ok_or("SERVICE_BOOK_DEPTH")?;need(!input.is_empty()&&input.len()<=20,"SERVICE_BOOK_DEPTH")?;let mut seen=BTreeSet::new();let mut output=Vec::new();for r in input{let text=if r["price"].is_number(){r["price"].to_string()}else{r["price"].as_str().ok_or("SERVICE_BOOK_PRICE")?.into()};let units=baal_transport_service::decimal_units(&text).map_err(|e|e.code)?;let p=money::price(&money::money(units))?;let q=r["quantity"].as_u64().ok_or("SERVICE_BOOK_QUANTITY")?;need(q>0&&q<=9007199254740991&&seen.insert(p),"SERVICE_BOOK_DEPTH")?;output.push((p,json!({"price":money::money(p),"quantity":q})));}output.sort_by_key(|x|if desc{-x.0}else{x.0});Ok(json!(output.into_iter().map(|x|x.1).collect::<Vec<_>>()))};let bids=levels("bids",true)?;let asks=levels("asks",false)?;need(money::amount(bids[0]["price"].as_str().unwrap())?<money::amount(asks[0]["price"].as_str().unwrap())?,"SERVICE_BOOK_CROSSED")?;
 Ok(json!({"tournamentId":config.tournament_id,"marketId":market,"exchangeId":exchange,"instrument":format!("{exchange}:YES"),"receivedAt":receipt.received_at,"requestStartedAt":receipt.request_started_at,"sourceAt":source_at,"sequence":sequence.to_string(),"versionKey":format!("{sequence}:{source_at}"),"bids":bids,"asks":asks,"freshnessPolicy":"authoritative_receipt_v1","sourceEventAgeMs":received-source_ms}))}
pub fn account_projection(reconciliation:&AccountReconciliation,previous:&Value)->Result<(Value,Value)>{let p=&reconciliation.positions;let o=&reconciliation.orders;let positions=p.data["positions"].as_array().ok_or("SERVICE_ACCOUNT_POSITIONS")?;let orders=o.data["data"].as_array().ok_or("SERVICE_ACCOUNT_ORDERS")?;let mut excluded=BTreeSet::new();let mut projected=Vec::new();for r in positions{let quantity=r["quantity"].as_i64().ok_or("SERVICE_ACCOUNT_QUANTITY")?;if quantity==0{continue}let exchange=r["exchangeId"].as_str().ok_or("SERVICE_ACCOUNT_SCOPE")?;excluded.insert(exchange.to_owned());projected.push(json!({"instrument":format!("{exchange}:{}",if quantity<0{"NO"}else{"YES"}),"exchangeId":exchange,"marketId":r["marketId"],"side":if quantity<0{"no"}else{"yes"},"quantity":quantity.unsigned_abs(),"cost":r["costBasis"],"avgCost":r["avgCost"],"valuationPrice":r["currentPrice"],"valuationValue":r["marketValue"],"unrealizedPnl":r["unrealizedPnl"],"label":r["marketTitle"]}));}let mut pending=Vec::new();for r in orders{if r["open"]!=true{continue}let exchange=r["exchangeId"].as_str().ok_or("SERVICE_ACCOUNT_SCOPE")?;excluded.insert(exchange.to_owned());pending.push(json!({"id":r["id"],"instrument":format!("{exchange}:{}",r["side"].as_str().unwrap_or("").to_ascii_uppercase()),"exchangeId":exchange,"side":r["side"],"action":r["action"],"quantity":r["quantity"],"limit":r["priceLimit"],"createdAt":r["createdAt"],"open":true}));}
 let eligibility=json!({"schemaVersion":1,"positionsAt":p.received_at,"ordersAt":o.received_at,"excludedExchangeIds":excluded.into_iter().collect::<Vec<_>>()});let mut view=previous.clone();view["mode"]=json!("official_account");view["available"]=json!(true);view["updatedAt"]=json!(reconciliation.completed_at);view["collectorStatus"]=json!("running");view["positions"]=json!(projected);view["pending"]=json!(pending);view["sourceTimes"]["positions"]=json!(p.received_at);view["sourceTimes"]["orders"]=json!(o.received_at);view["cash"]=json!(reconciliation.exact_cash);view["adoptsHoldings"]=json!(false);view["health"]=json!({"status":"partial","missingSections":["fills","pnl"]});Ok((eligibility,view))}
impl Service{
 pub fn collect_cycle(&mut self,transport:&mut Transport)->Result<()>{self.guard()?;let r=transport.reconcile().map_err(|e|e.code)?;let(eligibility,view)=account_projection(&r,&self.account_view)?;self.account=Some(eligibility);self.account_view=view;self.record_account(&r.completed_at)?;let markets=self.focus_markets(&r.completed_at)?;for market in markets{self.guard()?;let receipt=transport.request(Endpoint::OrderBook{market_id:market.clone(),depth:20}).map_err(|e|e.code)?;let book=normalize_book(&receipt,&market,&self.config)?;self.emit("book",json!({"book":book}),&receipt.received_at)?;}if self.config.account_extras{self.guard()?;let fills=transport.request(Endpoint::PortfolioFills).map_err(|e|e.code)?;let pnl=transport.request(Endpoint::Pnl).map_err(|e|e.code)?;let orders=r.orders.data["data"].as_array().ok_or("SERVICE_ACCOUNT_ORDERS")?;let rows=fills.data["data"].as_array().ok_or("SERVICE_ACCOUNT_FILLS")?;self.account_view["trades"]=json!(rows.iter().map(|f|{let action=orders.iter().find(|o|o["id"]==f["orderId"]).and_then(|o|o.get("action")).cloned().unwrap_or(Value::Null);json!({"id":f["id"],"orderId":f["orderId"],"instrument":format!("{}:{}",f["exchangeId"].as_str().unwrap_or(""),f["side"].as_str().unwrap_or("").to_ascii_uppercase()),"exchangeId":f["exchangeId"],"marketId":f["marketId"],"side":f["side"],"quantity":f["quantity"].as_i64().unwrap_or(0).unsigned_abs(),"price":f["price"],"at":f["filledAt"],"action":action})}).collect::<Vec<_>>());self.account_view["metrics"]=json!({"at":pnl.received_at,"accountValue":pnl.data["totalAccountValue"],"holdingsValue":pnl.data["totalHoldingsValue"],"costBasis":pnl.data["totalCostBasis"],"unrealizedPnl":pnl.data["unrealizedPnl"],"periodPnl":pnl.data["periodPnl"],"period":"day"});self.account_view["sourceTimes"]["fills"]=json!(fills.received_at);self.account_view["sourceTimes"]["pnl"]=json!(pnl.received_at);self.account_view["fillHistory"]=json!({"displayed":rows.len(),"hasMore":fills.data["pagination"]["hasMore"]});self.account_view["health"]=json!({"status":"fresh","missingSections":[]});self.account_view["updatedAt"]=json!(pnl.received_at);self.record_account(&pnl.received_at)?;}self.publish(&now())}
 pub fn transport_scope(&self)->Scope{Scope{tournament_id:self.config.tournament_id.clone(),tournament_slug:self.config.tournament_slug.clone(),exchanges:self.config.exchanges.clone()}}
 pub fn read_authority(&self,migration:Option<MigrationPermit>)->ServiceReadAuthority{let mut stops=self.config.stop_paths.clone();stops.push(self.config.runtime_dir.join("STOP"));ServiceReadAuthority{scope:self.transport_scope(),owner_path:self.config.runtime_dir.join("baal-service.lock"),owner_token:self.owner.token().into(),stops,migration}}
}
